-- Unit 1 word-family expansion: 75 new Word Families items (25 words x 3). DO NOT RUN until the teacher gives the final go-ahead.
-- Idempotent upserts.
begin;

on conflict (activity_content_id) do update set
  unit_number=excluded.unit_number,
  content_type=excluded.content_type,
  activity_data=excluded.activity_data,
  status=excluded.status,
  updated_at=now();
commit;
